import { existsSync, readFileSync, writeFileSync } from 'node:fs'

if (!existsSync('index.html') || !existsSync('public')) { console.error('Запускай из папки проекта (sunset-app).'); process.exit(1) }

const raw = readFileSync('index.html', 'utf8')
const crlf = raw.includes('\r\n')
let html = raw.replace(/\r\n/g, '\n')
if (html.includes('favicon-16.png')) { console.log('Уже применено'); process.exit(0) }

const lines = html.split('\n')
const idx = lines.findIndex((l) => /rel="icon"/.test(l))
if (idx < 0) { console.error('Не нашёл строку с иконкой в index.html. Ничего не менял.'); process.exit(1) }
const indent = lines[idx].match(/^\s*/)[0]
const block = [
  '<link rel="icon" href="/favicon.ico?v=3" sizes="any" />',
  '<link rel="icon" type="image/png" sizes="16x16" href="/favicon-16.png?v=3" />',
  '<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png?v=3" />',
  '<link rel="icon" type="image/png" sizes="192x192" href="/icon-192.png?v=3" />',
  '<link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png?v=3" />',
].map((l) => indent + l)
const kept = lines.filter((l, i) => i !== idx && !/rel="(icon|apple-touch-icon)"/.test(l))
kept.splice(idx, 0, ...block)
html = kept.join('\n')

const bin = {"public/favicon-16.png":"","public/favicon-32.png":"","public/icon-192.png":"","public/icon-512.png":"","public/apple-touch-icon.png":"","public/favicon.ico":""}
for (const [p, data] of Object.entries(bin)) { writeFileSync(p, Buffer.from(data, 'base64')); console.log('создан ' + p) }
writeFileSync('index.html', crlf ? html.replace(/\n/g, '\r\n') : html)
console.log('Готово: ваша иконка установлена. Дальше: npm run build, git add ., git commit, git push')
console.log('Браузер сильно кэширует иконку вкладки: после выкладки нажми Ctrl+F5, при необходимости закрой и открой вкладку.')
